const gcolors={project:['#eef3ff','#6585c1','project'],task:['#ecf6f0','#639e86','task'],knowledge:['#f3effb','#9985b7','knowledge'],memory:['#f3effb','#9985b7','knowledge'],event:['#fcf4e8','#c09e6a','calendar']};
let gx=0,gy=0,gzoom=1,scope='all',focusNode='',dragState=null,suppressClick=false;
const svg=$('#spaceSvg'),ns='http://www.w3.org/2000/svg';
function se(t,a={},text){const e=document.createElementNS(ns,t);Object.entries(a).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e}
function nodesShown(){const live=graphEdges.filter(e=>e.state!=='rejected');let ids=new Set(graphNodes.map(n=>n.id));if(scope==='suggestions'){ids=new Set(live.filter(e=>e.state==='suggested').flatMap(e=>[e.a,e.b]))}if(scope==='shared'){const hubs=graphNodes.filter(n=>['knowledge','memory','event'].includes(n.type)&&new Set(live.filter(e=>e.state!=='suggested'&&(e.a===n.id||e.b===n.id)).map(e=>e.a===n.id?e.b:e.a).filter(id=>id.startsWith('p:'))).size>1).map(n=>n.id);ids=new Set(hubs);live.filter(e=>e.state!=='suggested'&&(hubs.includes(e.a)||hubs.includes(e.b))).forEach(e=>{ids.add(e.a);ids.add(e.b)})}if(focusNode){const near=new Set([focusNode]);live.filter(e=>e.a===focusNode||e.b===focusNode).forEach(e=>{near.add(e.a);near.add(e.b)});ids=new Set([...ids].filter(id=>near.has(id)))}return graphNodes.filter(n=>ids.has(n.id))}
function drawSpace(){svg.replaceChildren();const defs=se('defs'),pattern=se('pattern',{id:'spacegrid',width:24,height:24,patternUnits:'userSpaceOnUse'});pattern.append(se('circle',{cx:1,cy:1,r:.7,fill:'#c8d5e7'}));defs.append(pattern);svg.append(defs,se('rect',{width:'100%',height:'100%',fill:'url(#spacegrid)'}));const world=se('g',{id:'spaceworld'});svg.append(world);const nodes=nodesShown(),ids=new Set(nodes.map(n=>n.id));const edges=graphEdges.filter(e=>e.state!=='rejected'&&ids.has(e.a)&&ids.has(e.b));edges.forEach(e=>{const a=graphNodes.find(n=>n.id===e.a),b=graphNodes.find(n=>n.id===e.b),g=se('g',{class:'graphlink',tabindex:0,role:'button','data-edge':e.id,'aria-label':e.label+'，'+(e.state==='suggested'?'AI 待确认':'已明确')});const ax=a.x+100,ay=a.y+43,bx=b.x+100,by=b.y+43,d=`M${ax} ${ay} L${bx} ${by}`;g.append(se('path',{d,class:'graph-hit'}),se('path',{d,fill:'none',stroke:e.state==='suggested'?'#baa3d3':'#b8c9df','stroke-width':1.6,'stroke-dasharray':e.state==='suggested'?'6 6':'none'}));const mx=(ax+bx)/2,my=(ay+by)/2,w=e.label.length*10+16;const label=se('g',{class:'graph-minor graphlabel'});label.append(se('rect',{x:mx-w/2,y:my-11,width:w,height:20,rx:7,fill:'#fafcff'}),se('text',{x:mx,y:my+3,'text-anchor':'middle','font-size':10,fill:e.state==='suggested'?'#a187b9':'#8395ad'},e.label));g.append(label);world.append(g)});nodes.forEach(n=>{const c=gcolors[n.type],g=se('g',{class:'graphnode',transform:`translate(${n.x} ${n.y})`,tabindex:0,role:'button','data-node':n.id,'aria-label':n.label+'，点击详情，拖动调整位置'});g.append(se('rect',{width:200,height:86,rx:17,fill:'#fff',stroke:c[1],'stroke-opacity':'.55'}),se('rect',{x:12,y:14,width:29,height:29,rx:9,fill:c[0]}));const ic=se('svg',{x:18,y:20,width:17,height:17,viewBox:'0 0 24 24',fill:'none',stroke:c[1],'stroke-width':1.6,'stroke-linecap':'round','stroke-linejoin':'round'});ic.append(se('use',{href:'#i-'+c[2]}));g.append(ic,se('text',{x:51,y:33,'font-size':13,fill:'#405574','font-weight':550},n.label),se('text',{x:14,y:62,'font-size':10,fill:'#8b99ad',class:'graph-minor'},n.sub));world.append(g)});transformSpace();$('#graphstatus').textContent=`当前 ${nodes.length} 个对象 · ${edges.length} 条关系 · ${edges.filter(e=>e.state==='suggested').length} 条 AI 待确认建议。`}
function transformSpace(){const w=$('#spaceworld');if(!w)return;w.setAttribute('transform',`translate(${gx} ${gy}) scale(${gzoom})`);w.classList.toggle('semantic-small',gzoom<.6);$('#zoomlabel').textContent=Math.round(gzoom*100)+'%'}
function fitSpace(){const nodes=nodesShown(),r=svg.getBoundingClientRect();if(!r.width||!nodes.length){gx=20;gy=20;gzoom=1;transformSpace();return}const x=Math.min(...nodes.map(n=>n.x)),y=Math.min(...nodes.map(n=>n.y)),w=Math.max(...nodes.map(n=>n.x+200))-x,h=Math.max(...nodes.map(n=>n.y+86))-y;gzoom=Math.min(1.1,(r.width-70)/w,(r.height-95)/h);gx=(r.width-w*gzoom)/2-x*gzoom;gy=(r.height-h*gzoom)/2-y*gzoom;transformSpace()}
function zoomAt(factor,x,y){const next=Math.max(.25,Math.min(2.5,gzoom*factor)),r=next/gzoom;gx=x-(x-gx)*r;gy=y-(y-gy)*r;gzoom=next;transformSpace()}
function launchSpace(id=''){close();scope='all';focusNode=id;$('#scopefilter').value='all';$('#projectfocus').value=id.startsWith('p:')?id:'';show('space');drawSpace();fitSpace()}
const originalShow=show;show=function(v){originalShow(v);if(v==='space'){drawSpace();fitSpace()}};
const originalOpen=open;open=function(title,type,html){originalOpen(title,type,html);document.querySelector('main').inert=true;$('.nav').inert=true;const n=graphNodes.find(n=>n.label===title);if(n){const b=document.createElement('button');b.className='btn';b.style.marginTop='16px';b.textContent='在关联空间中查看';b.onclick=()=>launchSpace(n.id);$('#detailbody').append(b)}};
const originalClose=close;close=function(){document.querySelector('main').inert=false;$('.nav').inert=false;originalClose()};$('.close').onclick=close;
function edgeDetail(id){const e=graphEdges.find(e=>e.id===id),a=graphNodes.find(n=>n.id===e.a),b=graphNodes.find(n=>n.id===e.b);open(e.label,'RELATION / 示例关系证据',`<p>${a.label} → ${b.label}</p><div class="proof"><b>为什么关联</b><br>${e.why}<br><br><b>来源依据（示例）</b><br>${e.source}</div><p>状态：${{fact:'明确引用',suggested:'AI 建议 · 未确认',accepted:'本页演示中已接受',rejected:'本页演示中已驳回'}[e.state]}</p>${e.confidence?`<p>判断强度：${e.confidence}</p>`:''}<p class="notice">判断强度不是校准后的正确概率。正式版本保留来源版本、有效时间、权限范围和失效状态。</p><div class="modalactions">${e.state==='suggested'?`<button class="btn primary" data-decision="accepted" data-rel="${e.id}">接受关联 · 演示</button><button class="btn" data-decision="rejected" data-rel="${e.id}">驳回关联 · 演示</button>`:e.state==='accepted'||e.state==='rejected'?`<button class="btn" data-decision="suggested" data-rel="${e.id}">撤销本次判断</button>`:''}<button class="btn" data-focusnode="${e.a}">聚焦起点</button><button class="btn" data-focusnode="${e.b}">聚焦终点</button></div><p class="notice">关系判断只更新此页面；不会写入 Mnemon、业务数据库或真实资料。</p>`)}
function nodeDetail(id){const n=graphNodes.find(n=>n.id===id);if(n.type==='project'||n.type==='task'||n.type==='knowledge'||n.type==='memory'||n.type==='event'){launchSpace(id);toast('已展开「'+n.label+'」及其关联节点');return}const es=graphEdges.filter(e=>e.state!=='rejected'&&(e.a===id||e.b===id));open(n.label,'OBJECT / 共享对象',`<p>${n.sub}</p><div class="proof">此节点代表一个对象。多个项目连接到同一对象，保留相同来源和版本引用。</div><h3>关联关系 · 点击查证</h3><div class="relationlist">${es.map(e=>`<button class="btn" data-relation="${e.id}">${e.label}${e.state==='suggested'?' · AI 建议':''}</button>`).join('')}</div><p class="notice">记忆是历史背景与经验来源，不能直接覆盖当前项目状态。跨项目共享也必须遵守访问权限。</p>`)}
svg.addEventListener('wheel',e=>{e.preventDefault();const r=svg.getBoundingClientRect();zoomAt(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top)},{passive:false});
svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;const node=e.target.closest('[data-node]'),n=node?graphNodes.find(n=>n.id===node.dataset.node):null;dragState={id:e.pointerId,x:e.clientX,y:e.clientY,gx,gy,n,nx:n?.x,ny:n?.y,moved:false};suppressClick=false;svg.setPointerCapture(e.pointerId)});
svg.addEventListener('pointermove',e=>{if(!dragState||e.pointerId!==dragState.id)return;const dx=e.clientX-dragState.x,dy=e.clientY-dragState.y;if(Math.abs(dx)+Math.abs(dy)>4)dragState.moved=true;if(!dragState.moved)return;if(dragState.n){dragState.n.x=dragState.nx+dx/gzoom;dragState.n.y=dragState.ny+dy/gzoom;drawSpace()}else{gx=dragState.gx+dx;gy=dragState.gy+dy;transformSpace()}});
svg.addEventListener('pointerup',e=>{if(!dragState)return;suppressClick=dragState.moved;dragState=null;if(!suppressClick){const hit=document.elementFromPoint(e.clientX,e.clientY),n=hit?.closest('[data-node]'),edge=hit?.closest('[data-edge]');if(n)nodeDetail(n.dataset.node);else if(edge)edgeDetail(edge.dataset.edge)}});svg.addEventListener('pointercancel',()=>{dragState=null});svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const n=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');if(n||edge)e.preventDefault();if(n)nodeDetail(n.dataset.node);if(edge)edgeDetail(edge.dataset.edge)}});
$('#more').onclick=()=>{const r=svg.getBoundingClientRect();zoomAt(1.2,r.width/2,r.height/2)};$('#less').onclick=()=>{const r=svg.getBoundingClientRect();zoomAt(1/1.2,r.width/2,r.height/2)};$('#fitspace').onclick=fitSpace;
const initialPositions=graphNodes.map(n=>({id:n.id,x:n.x,y:n.y}));$('#resetlayout').onclick=()=>{initialPositions.forEach(p=>Object.assign(graphNodes.find(n=>n.id===p.id),p));drawSpace();fitSpace()};
$('#scopefilter').onchange=e=>{scope=e.target.value;focusNode='';$('#projectfocus').value='';drawSpace();fitSpace()};$('#projectfocus').onchange=e=>{focusNode=e.target.value;scope='all';$('#scopefilter').value='all';drawSpace();fitSpace()};$('#graphsearch').onkeydown=e=>{if(e.key!=='Enter')return;const q=e.target.value.trim();if(!q)return;const n=graphNodes.find(n=>n.label.includes(q));if(!n){toast('未找到匹配的示例节点');return}launchSpace(n.id)};
$('#aiExplain').onclick=()=>open('AI 发现关系，记忆提供背景','DESIGN / 拟实现架构',`<div class="phase">${['授权输入','检索召回','AI 推断','证据校验','关系呈现'].map(x=>`<span class="done">${x}</span>`).join('')}</div><h3>三种职责分别保存</h3><div class="proof">业务记录：项目、任务、会议与当前状态。<br>记忆与知识：历史背景、经验、资料和引用证据。<br>关系层：对象 ID、关联类型、依据、来源版本、确认和失效状态。</div><h3>由 AI 提议，由证据约束</h3><p>新增资料或任务产物 → 在授权范围内检索相关项目与记忆 → AI 给出候选关系及理由 → 检查对象、来源、重复与权限 → 虚线展示待确认建议。</p><p>已有明确归属与引用直接显示；模型推测不自动变成事实。用户否定后保留反馈，避免相同证据重复推荐。原文更新、权限撤回或事实失效时重新评估。</p><h3>和记忆如何打通</h3><p>通过受控适配器召回与引用 Mnemon、knowledge。确认关系保存在业务关系层；只有符合持久记忆策略的经验才写入记忆，不把整张图反复灌回记忆。</p><p class="notice">当前只是演示上述交互，尚未实现 AI 推断服务、接口适配或自动失效传播。Host 服务目录未暴露对应插件的直接契约，需进一步验证集成路径。</p>`);
$('#globalCanvas').onclick=()=>{scope='all';focusNode='';$('#scopefilter').value='all';$('#projectfocus').value='';drawSpace();fitSpace();toast('已回到全局视图，展示全部关联对象。')};
$('#allrelations').onclick=()=>open('关系与证据','RELATIONS / 示例清单',`<p>包含已驳回建议，可撤销当前页中的判断。</p><div class="relationlist">${graphEdges.map(e=>`<button class="btn" data-relation="${e.id}">${e.label} · ${{fact:'明确',suggested:'待确认',accepted:'已接受',rejected:'已驳回'}[e.state]}</button>`).join('')}</div>`);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.relation)edgeDetail(b.dataset.relation);if(b.dataset.focusnode)launchSpace(b.dataset.focusnode);if(b.dataset.decision){const edge=graphEdges.find(x=>x.id===b.dataset.rel);edge.state=b.dataset.decision;drawSpace();edgeDetail(edge.id)}});
new ResizeObserver(()=>{if(current==='space')transformSpace()}).observe(svg);
